// =============================================================================
//  OncoSense Band — on-device neural network
//
//  A 12 -> 16 -> 12 -> 5 multilayer perceptron (ReLU, softmax) whose weights
//  are generated by ml/train.py into model_weights.h. Inference is plain
//  float C++ (no TensorFlow Lite needed), runs in well under 1 ms on a
//  SAMD21, and uses about 2 KB of flash.
//
//  Personalization: the output layer lives in RAM and can be fine-tuned on
//  the band from a few readings the wearer labels themselves (command `t`).
//  An L2 pull toward the factory weights stops a handful of samples from
//  wrecking the model.
// =============================================================================
#pragma once

#include <stdint.h>

namespace oncosense {

class NeuralNet {
 public:
  static const int kInputs = 12;
  static const int kHidden = 12;  // width of the last hidden layer
  static const int kClasses = 5;
  static const int kMaxExamples = 24;

  NeuralNet();

  // probs[kClasses] receives softmax probabilities; returns the argmax.
  // hidden (optional, kHidden floats) receives the last hidden layer.
  int predict(const float *features, float *probs, float *hidden = nullptr) const;

  // Out-of-distribution score: RMS of the standardized features. Around 1
  // for readings like the training data; well above 3 means "unlike anything
  // the model has seen", so the prediction should not be trusted.
  float outOfDistribution(const float *features) const;

  // Add a wearer-labelled example and re-fit the output layer on all stored
  // examples. Returns the fit accuracy on the stored examples.
  float personalize(const float *features, int label, int epochs = 40, float lr = 0.05f);

  void resetHead();
  bool isPersonalized() const { return personalized_; }
  int exampleCount() const { return numExamples_; }

  // Head weights, for saving to / loading from flash.
  float headW[kClasses * kHidden];
  float headB[kClasses];
  void markPersonalized() { personalized_ = true; }

  static const char *className(int i);
  // Fingerprint of the compiled-in weights (generated by ml/train.py).
  static uint32_t modelId();

 private:
  void hiddenLayer(const float *features, float *h2) const;

  float exHidden_[kMaxExamples][kHidden];
  uint8_t exLabel_[kMaxExamples];
  int numExamples_ = 0;
  int nextSlot_ = 0;
  bool personalized_ = false;
};

}  // namespace oncosense
